// EXPORTS: IEra, IHistoryNode, ERAS, HISTORY_NODES, CIVILIZATIONS, CATEGORIES, CIVILIZATION_COLORS

export type CivilizationKey =
  | 'china'
  | 'europe'
  | 'middleEast'
  | 'southAsia'
  | 'eastAsia'
  | 'america'
  | 'africa'
  | 'centralAsia'
  | 'oceania'
  | 'global';

export type CategoryKey =
  | 'politics'
  | 'military'
  | 'science'
  | 'culture'
  | 'myth'
  | 'artifact';

export interface IEra {
  id: string;
  name: string;
  nameEn: string;
  startYear: number; // 负数=公元前
  endYear: number;
  description: string;
  bgFrom: string; // 背景渐变色起点 (hex)
  bgTo: string; // 背景渐变色终点
  accent: string; // 时代强调色
}

export type HistoryNodeType = 'event' | 'person' | 'myth' | 'dynasty' | 'artifact';

export interface IHistoryNode {
  id: string;
  title: string;
  year: number; // 负数=公元前，用于排序
  yearDisplay: string; // 展示用文字
  civilization: CivilizationKey;
  categories: CategoryKey[];
  eraId: string;
  type?: HistoryNodeType; // 节点类型：事件/人物/神话，默认 event
  location?: { lat: number; lng: number }; // 地图坐标
  summary: string; // 一句话摘要
  description: string; // 详细介绍 300-800字
  imageEra: string; // 对应的时代图片 key
  relatedNodeIds: string[]; // 关联节点
  important?: boolean; // 是否重要节点（更大的圆点）
  disputed?: string; // 学术争议说明（如有）
  keyPoints?: string[]; // 核心记忆点 3-5 条
}

