    summary: '人类演化的开端，最早的人科动物出现在非洲东部。',
    description:
      `南方古猿（Australopithecus）是已灭绝的人科动物，被认为是人类进化史上的关键阶段，也是目前已知最早的两足行走的人科动物之一。它们生活在距今约420万至190万年前的非洲，主要分布在东非和南非。"南方古猿"之名源于其化石最初在南非被发现——拉丁语australis意为"南方"，希腊语pithekos意为"猿"。

南方古猿的发现是人类进化研究的里程碑。1924年，澳大利亚解剖学家雷蒙德·达特在南非汤恩（Taung）发现了一具幼年古猿的头骨化石，他将其命名为"非洲南方古猿"（Australopithecus africanus），并指出这是人类与猿类之间的过渡类型。这一发现当时遭到了学术界的普遍质疑——因为当时人们普遍认为人类起源于亚洲，而且大脑的增大应该早于两足行走。但后来的发现证明达特是正确的。

最著名的南方古猿化石是1974年在埃塞俄比亚阿法尔地区发现的"露西"（Lucy）——这是一具保存了约40%骨骼的雌性个体，属于阿法南方古猿（Australopithecus afarensis），生活在距今约320万年前。露西的发现震惊了世界，因为她清楚地证明了两足行走先于大脑容量增大——露西的脑容量只有约400-500毫升（与现代黑猩猩相当），但她的骨盆和腿骨结构明确显示她已经能够直立行走。这颠覆了此前"大脑先行"的人类进化假说。

南方古猿具有以下主要特征：一是两足行走，骨盆短而宽（适应直立行走），股骨角度向内（膝盖靠近身体中线），足弓发育良好；但他们可能仍保留了部分树栖能力——手臂相对较长，手指弯曲。二是脑容量小，约400-500毫升，仅为现代人的三分之一左右，与黑猩猩相当。三是身高体轻，成年个体身高约1.0-1.5米，体重约25-50公斤，有明显的性别二态性（雄性比雌性大得多）。四是面部突出，颧骨高，颌骨突出，没有明显的下巴，牙齿较大（尤其臼齿），适合咀嚼坚硬的植物性食物。

南方古猿有多个物种，包括较为纤细的阿法南方古猿、非洲南方古猿，以及较为粗壮的傍人（Paranthropus，曾被称为"粗壮型南方古猿"，如鲍氏傍人、粗壮傍人、埃塞俄比亚傍人）。粗壮型的南方古猿有巨大的臼齿和发达的咀嚼肌，可能以坚硬的植物根茎和种子为食。

目前的人类进化谱系中，人属（Homo）被认为是从某种纤细型南方古猿演化而来的——可能是阿法南方古猿或非洲南方古猿的某个分支。大约240万年前，最早的人属成员——能人（Homo habilis）出现在东非，他们的脑容量更大，并且确定会制造石器工具。此后，人属逐渐取代了南方古猿，成为人类进化的主线。

南方古猿在人类进化史上的地位至关重要——他们是我们从猿类分化出来后第一个成功的演化分支，也是两足行走这一人类标志性特征的开创者。`,
