    title: '能人出现，石器时代开端',
    year: -2500000,
    yearDisplay: '约250万年前',
    civilization: 'africa',
    categories: ['science', 'artifact'],
    type: 'artifact',
    eraId: 'prehistoric',
    location: { lat: -2, lng: 37 },
    summary: '能人开始制造石器工具，旧石器时代正式开始。',
    description: `能人（Homo habilis）是古人类的一个种，生活在距今约240万年前到140万年前的非洲，属于人属（Homo）中最早的成员之一。能人是由古人类学家路易斯·利基和玛丽·利基夫妇于1960年代在坦桑尼亚的奥杜威峡谷发现的，他们在1964年将其命名为"能人"，意思是"手巧的人"，因为他们被认为是最早的石器制造者。

能人生活在东非的热带草原环境中。他们的体型比南方古猿稍大，但身高也只有约1.2到1.4米，体重大约40到50公斤。能人的脑容量约为600到750毫升，比南方古猿（约400到500毫升）大得多，但比直立人（约900到1100毫升）小。能人的面部特征比较原始，眉骨突出，颌骨粗壮，牙齿也比较大。

能人最显著的成就是制造和使用石器。他们制造的石器被考古学家称为"奥杜威文化"（Oldowan），因最早发现于奥杜威峡谷而得名。奥杜威石器是最原始的石器类型，主要是用一块石头敲击另一块石头，打制出简单的石片和石核。这些石器虽然简陋，但它们是人类主动制造工具的标志，是人类与其他动物的重要区别之一。

能人用这些石器做什么呢？考古学家认为，能人可能用石器来切割动物的肉、砸碎骨头取食骨髓。也就是说，能人可能已经开始吃肉了，这在人类进化史上具有重要意义——肉类是高能量食物，有助于大脑的发育。不过，能人主要是食腐还是狩猎，目前学术界还有争议。一般认为，能人主要靠采集植物和食腐为生，狩猎可能还不是主要的生存方式。

能人是人类进化树上的重要一环。他们是最早的人属成员，是我们的直系祖先之一。他们制造的石器，标志着人类进入了旧石器时代。从能人开始，人类大脑的容量开始显著增大，技术也开始不断进步。能人的出现，是人类进化史上的一个重要里程碑——它开启了人类以工具和智慧适应环境的新时代。`,
