    description:
      '智人（Homo sapiens）即我们现代人所属的物种，最早出现在约30万年前的非洲。在此后漫长的岁月里，智人与其他古人类物种共存，包括欧洲和西亚的尼安德特人（Homo neanderthalensis）以及亚洲的直立人后裔。\n\n尼安德特人是与智人关系最近的已灭绝人类物种，它们身体强壮，适应冰河时期的寒冷气候，脑容量甚至比现代人大。尼安德特人会制造复杂的石器、使用火、埋葬死者，甚至可能拥有原始的语言和艺术。\n\n大约7万年前，智人开始大规模走出非洲，逐步扩散到世界各地。在这个过程中，智人与尼安德特人有过基因交流——现代非非洲裔人类的基因组中含有1-4%的尼安德特人基因。约3万年前，尼安德特人最终灭绝，智人成为地球上唯一的人类物种。',
