    description:
      `智人走出非洲与认知革命是人类历史上最重大的事件之一。大约30万年前，智人（Homo sapiens，即我们现代人）在非洲演化出现；大约7万年前，一部分智人走出非洲，向世界各地扩散，并最终取代了其他所有的原始人类（如尼安德特人、丹尼索瓦人、弗洛勒斯人等），成为地球上唯一的人类物种。这一事件被称为"走出非洲"（Out of Africa），而与之相伴随的人类认知能力的飞跃，则被称为"认知革命"（Cognitive Revolution）。

根据目前的考古学和遗传学证据，智人起源于非洲的时间大约在30万年前。最早的智人化石发现于摩洛哥的杰贝尔伊德遗址（Jebel Irhoud），距今约31.5万年。此后的20多万年里，智人一直生活在非洲大陆上，与其他多种人属物种共存。

大约7万年前，一次重大的事件改变了人类的命运——认知革命发生了。历史学家尤瓦尔·赫拉利在《人类简史》中提出了这一概念，认为大约7万年前，智人的大脑结构发生了某种变化，使他们获得了全新的思维方式和语言能力——尤其是虚构故事的能力。这种能力使智人能够相信不存在于现实中的事物（神、国家、金钱、法律等），从而能够进行大规模的灵活协作——这是其他任何动物都做不到的。

认知革命的考古学证据包括：艺术的出现（约7万年前出现了最早的贝壳串珠和雕刻品；约4万年前出现了精美的洞穴壁画和雕塑）、工具的复杂化（石器工具变得更加精细多样，出现了骨器、鱼钩、投矛器等新工具）、远距离贸易（不同地区的人群之间已经开始交换贝壳、黑曜石等珍贵物品）、丧葬仪式（开始出现有意识的墓葬，随葬品表明人类已经有了来世观念和宗教信仰）。

正是在认知革命之后，智人开始了大规模的迁徙。约7万年前，智人走出非洲，首先到达了中东和阿拉伯半岛，然后分几支向不同方向扩散：向南，约6.5万年前到达印度，约6万年前到达东南亚和澳大利亚——值得注意的是，当时澳大利亚与新几内亚连在一起，形成一个大陆块，智人必须乘船才能到达，这证明了智人已经具备了航海能力。向东北，约5万年前进入中亚，然后向西进入欧洲，向东进入东亚。在欧洲和西亚，智人与尼安德特人共存了约一万年，最终尼安德特人在约4万年前灭绝。现代基因组研究表明，非非洲裔的现代人基因组中含有约1-4%的尼安德特人基因，说明两个物种之间曾经发生过混血。向美洲，约2-1.5万年前（具体时间仍有争议），智人通过白令陆桥进入美洲，然后迅速向南扩散，在约1000年的时间里就到达了南美洲的最南端。

到了约1万年前，智人已经遍布除了南极洲以外的所有大陆和主要岛屿。在这个过程中，地球上其他所有的原始人类物种都灭绝了——尼安德特人、丹尼索瓦人、弗洛勒斯人（霍比特人）——智人成为了唯一幸存的人类物种。

走出非洲和认知革命的影响是深远的：它们标志着人类从一种普通的非洲灵长类动物，转变为能够改变整个星球的"超级物种"。正是认知革命赋予了我们虚构故事的能力，使大规模协作成为可能，从而催生了农业革命、城市、国家、科学革命和现代文明。`,
    imageEra: 'prehistoric',
    relatedNodeIds: ['homo-sapiens', 'ice-age-end'],
    important: true,
