    description:
      '约公元前6000年（约8000年前），人类最早的城市开始出现在世界各地。其中最著名的是位于今天巴勒斯坦的杰里科（Jericho），它被誉为"世界上最古老的城市"。\n\n杰里科坐落在死海以北的绿洲中，得益于丰富的泉水，早在农业革命初期就有人定居。到公元前8000年左右，杰里科已经发展为一个有城墙环绕的城镇。最令人惊叹的是一座高约8米的石塔，由内部石阶连接顶部，这是人类最早的大型石造建筑之一。城墙和塔楼的存在表明，当时的社会已经有了足够的人口、组织能力和资源来进行公共工程建设。\n\n差不多同一时期，安纳托利亚（今土耳其）的恰塔霍裕克（Çatalhöyük）发展出独特的城市形态——房屋紧密相连，没有街道，人们从屋顶进出。这些早期城市虽然与现代城市形态迥异，但它们标志着人类社会组织的一次飞跃：从村落走向城市。',
