    description:
      '约公元前4000年（约6000年前），在底格里斯河和幼发拉底河之间的美索不达米亚平原上，苏美尔人建立了人类最早的城邦国家。这一地区被称为"两河流域"，是人类文明的摇篮之一。\n\n苏美尔人发展出灌溉农业，在干旱的平原上建造了复杂的运河系统。他们冶炼铜和青铜，制造工具和武器——铜器时代由此开始。手工业和贸易蓬勃发展，为了管理神庙和城邦的财富，他们发明了人类最早的书写系统——楔形文字。\n\n苏美尔的城邦（如乌鲁克、乌尔、拉格什）彼此独立，经常互相征战。每个城邦都有自己的保护神和神王（祭司国王）。苏美尔人创造了丰富多彩的神话传说，其中最著名的是《吉尔伽美什史诗》——人类历史上最早的史诗作品。苏美尔文明虽然历经数千年最终消亡，但它的遗产通过巴比伦、亚述、波斯等后继文明传承下来，深刻影响了整个中东乃至世界。',
