    description:
      '黄帝被尊为中华民族的人文始祖，传说生活在约公元前2700年。虽然黄帝时代的真实性在学术界仍有争议，但作为文化记忆，黄帝的传说深刻塑造了中国人的身份认同。\n\n根据传说，黄帝姓姬，号轩辕氏，是有熊氏部落的首领。他与炎帝部落结盟，在涿鹿之战中击败了东方的蚩尤部落，统一了中原各部落。炎黄联盟被视为华夏民族的起源，中国人因此自称"炎黄子孙"。\n\n黄帝时代被认为是中华文明诸多发明的源头：史官仓颉创造了文字，妻子嫘祖发明了养蚕缫丝，大臣隶首发明了算数，伶伦制定了音律。这些传说固然有后人附会的成分，但它们反映了一个事实：在距今约五千年的仰韶文化晚期到龙山文化时期，中华文明的诸多要素已经在黄河流域孕育成形。城址、玉器、礼制、铜器的考古发现，都在为传说时代提供着越来越多的实物证据。',
