    description:
      '公元前2070年左右，传说中的夏朝建立，这是中国历史上第一个世袭制王朝。夏朝的建立标志着中国从原始社会的部落联盟迈入了国家形态。\n\n夏朝的奠基者是大禹，因成功治理洪水而深受民众拥戴。禹之前，部落联盟首领的位置通过"禅让制"传承——选贤任能，将权力传给最有能力的人。大禹死后，他的儿子启夺取了王位，从此"公天下"变成了"家天下"，王位世袭制取代了禅让制。\n\n夏朝的历史在很长时间里被视为传说，因为缺乏直接的文字证据。但近年来的考古发现，尤其是河南偃师二里头遗址，为夏朝的存在提供了越来越多的实物支持。二里头遗址发现了大型宫殿基址、青铜礼器和贵族墓葬，年代约为公元前1750-1500年，与史书记载的夏朝中晚期相当。夏朝的建立是中华文明从部落时代走向王朝时代的关键转折点。',
