    summary: '雅利安人进入印度次大陆，吠陀文明兴起，种姓制度萌芽。',
    description:
      '公元前1500年左右，说印欧语系语言的游牧部落——雅利安人（Aryans）——从中亚草原进入印度次大陆，逐渐征服和同化了当地居民。这次迁徙对印度文明产生了深远而持久的影响。\n\n雅利安人带来了他们的宗教经典《吠陀》（Vedas），这是用梵语写成的最古老的印度文献。《梨俱吠陀》是其中最古老的一部，包含了上千首献给诸神的颂歌。吠陀宗教是后来印度教的源头——梵天、毗湿奴、湿婆等印度教大神的形象，都可以在吠陀文献中找到雏形。\n\n雅利安人的到来也开启了印度种姓制度的历史。最初，社会分为三个阶层：婆罗门（祭司）、刹帝利（武士贵族）和吠舍（平民），被征服者成为首陀罗（奴隶和劳工）。后来又出现了"不可接触者"（达利特）。种姓制度在印度延续了三千多年，虽然现代印度在法律上废除了种姓歧视，但它仍然深刻影响着印度社会。',
