    summary: '摩西带领以色列人出埃及，一神教传统由此奠基。',
    description:
      '根据《圣经·出埃及记》记载，摩西（Moses）带领在埃及为奴的以色列人逃离埃及，穿越红海，前往上帝应许之地迦南。这一事件被视为犹太民族历史上最重要的事件，也是三大一神教（犹太教、基督教、伊斯兰教）共同的精神源头。\n\n在西奈山上，摩西从上帝那里领受了"十诫"，这成为犹太教律法的核心。十诫确立了"除了我以外，你不可有别的神"的一神教原则——这在多神教盛行的古代世界是革命性的观念。与当时其他宗教不同，犹太教的神没有形象，不可被雕刻为偶像，而是无形无象、全知全能的宇宙创造者。\n\n历史学家对摩西出埃及的历史真实性仍有争议。虽然埃及文献中没有明确记载，但这一传说的文化意义远超历史事实本身。犹太教的一神论思想后来通过基督教和伊斯兰教传遍了世界，深刻改变了人类的精神面貌和历史进程。今日西方文明的伦理观念、法律传统和时间观念，都深受这一传统的影响。',

