    categories: ['politics', 'culture'],
    type: 'event',
    eraId: 'ancient',
    location: { lat: 34.6, lng: 112.4 },
    summary: '周平王东迁洛邑，东周开始，春秋时代，礼崩乐坏。',
    description:
      '公元前770年，犬戎攻破西周都城镐京，周幽王被杀。周平王将都城东迁至洛邑（今河南洛阳），史称东周。东周的前半段被称为"春秋时期"（因鲁国编年史《春秋》而得名），是一个大动荡、大变革的时代。\n\n东迁之后，周天子的权威一落千丈，诸侯不再听从天子的命令。"礼崩乐坏"成为时代的关键词——原本维系社会秩序的礼乐制度逐渐瓦解，各国之间战争频繁，强者生存，弱者灭亡。据记载，春秋初期有140多个诸侯国，到春秋末期只剩下约20个。\n\n在这个动荡的时代，一批杰出的政治家和思想家登上历史舞台。齐国的管仲辅佐齐桓公"九合诸侯，一匡天下"，成为春秋第一位霸主；郑国的子产"铸刑书"，开创了中国公布成文法的先河。更重要的是，随着旧秩序的瓦解，思想的闸门被打开了——这为后来战国时期的"百家争鸣"奠定了基础。春秋是中国思想文化大繁荣的前夜。',
