    location: { lat: 35.6, lng: 116.9 },
    summary: '儒家学派创始人，中国历史上最伟大的思想家、教育家，被尊为"至圣先师"。',
    description:
      '孔丘，字仲尼，春秋末期鲁国陬邑（今山东曲阜）人，儒家学派创始人，中国历史上最伟大的思想家、教育家。先世为宋国贵族，因避内乱迁居鲁国。父叔梁纥是鲁国武士，孔丘三岁丧父，家道中落，"吾少也贱，故多能鄙事"。\n\n十五而志于学，三十而立。年轻时做过委吏（管仓库）和乘田（管牛羊），以知礼闻名。约三十岁开始收徒讲学，开创了私人讲学之风。五十岁左右出任鲁国中都宰，一年后升任司空、大司寇，摄相事，"三月而鲁国大治"。因与季氏政见不合，五十五岁率众弟子周游列国，历经卫、曹、宋、郑、陈、蔡、楚等国，前后十四年，宣扬仁政德治的主张而屡遭困厄，"知其不可而为之"。\n\n六十八岁时返鲁，晚年致力于教育和文献整理。他整理《诗》《书》《礼》《乐》《易》《春秋》六经，删《诗》为三百零五篇，序《书传》，订《礼》《乐》，赞《周易》（作十翼），修《春秋》（以一字寓褒贬的编年体史书）。相传有弟子三千、贤人七十二，著名的有颜回、子路、子贡、曾参等。\n\n孔子思想的核心是"仁"——"仁者爱人""己所不欲，勿施于人""己欲立而立人，己欲达而达人"。仁是内在的道德自觉，礼是外在的行为规范，"克己复礼为仁"。政治上主张"为政以德"，"道之以德，齐之以礼，有耻且格"，反对苛政和刑杀。教育上主张"有教无类"和"因材施教"，"学而时习之""温故而知新""学而不思则罔，思而不学则殆""三人行，必有我师焉"。\n\n公元前479年，孔子卒，享年七十三岁，葬于鲁城北泗水之上。其弟子及再传弟子将他的言行整理为《论语》二十篇，是儒家最重要的经典。孔子开创的儒家思想经孟子、荀子发展，汉武帝"罢黜百家，独尊儒术"后成为中国两千年的正统思想，深刻塑造了东亚文明圈。他被尊为"至圣先师""万世师表"，位列"世界十大文化名人"之首。',

