    eraId: 'classical',
    location: { lat: 33.9, lng: 117.2 },
    summary: '西楚霸王，中国历史上最勇猛的武将之一，楚汉相争的悲剧英雄。',
    description:
      '名籍，字羽，楚国下相（今江苏宿迁）人，楚国名将项燕之孙，秦末起义军领袖，自号"西楚霸王"。身长八尺余（约一米八五以上），力能扛鼎，才气过人，少年时见秦始皇南巡的车队，脱口而出"彼可取而代也"。\n\n公元前209年，陈胜吴广在大泽乡起义，项羽随叔父项梁在会稽起兵响应，率八千江东子弟渡江而西。项梁战死后，楚怀王命宋义为上将军、项羽为次将北上救赵。宋义畏敌不前，项羽在帐中斩宋义头，自领军渡河，"皆沉船，破釜甑，烧庐舍，持三日粮，以示士卒必死，无一还心"——这就是"破釜沉舟"的由来。巨鹿之战中，项羽以数万楚军大败秦将章邯、王离的四十万大军，"楚战士无不一以当十，楚兵呼声动天，诸侯军无不人人惴恐"。战后项羽召见诸侯将，他们"无不膝行而前，莫敢仰视"。\n\n项羽率军入关中，杀秦王子婴，烧阿房宫，大火三月不灭。他分封十八路诸侯，自立为西楚霸王，都彭城，封刘邦为汉王。此后与刘邦展开了长达四年的楚汉战争。彭城之战，项羽以三万精骑大败刘邦五十六万联军，睢水为之不流。荥阳对峙、鸿沟为界，项羽一度占尽上风。但他刚愎自用，不听亚父范增的忠告，在鸿门宴上放走刘邦；不善用人，韩信、陈平、英布等纷纷叛楚归汉；后方不稳，粮草不继。\n\n公元前202年，项羽被韩信、彭越、英布等各路汉军围于垓下，兵少食尽。夜间四面皆楚歌，项羽大惊："汉皆已得楚乎？是何楚人之多也！"他夜起饮帐中，面对爱妾虞姬和乌骓马，慷慨悲歌："力拔山兮气盖世，时不利兮骓不逝。骓不逝兮可奈何，虞兮虞兮奈若何！"——这就是著名的"霸王别姬"。项羽率八百余骑突围，至东城只剩二十八骑。最后退至乌江，乌江亭长劝他渡江，他日东山再起，项羽笑道："天之亡我，我何渡为！且籍与江东子弟八千人渡江而西，今无一人还，纵江东父兄怜而王我，我何面目见之？"遂自刎而死，年仅三十岁。\n\n项羽虽然失败，却成为中国历史上最著名的悲剧英雄。司马迁在《史记》中破例将他列入帝王体例的《本纪》，李清照有诗云："生当作人杰，死亦为鬼雄。至今思项羽，不肯过江东。"',
