    eraId: 'classical',
    location: { lat: 34.6, lng: 112.4 },
    summary: '刘秀建立东汉，蔡伦改进造纸术，对人类文明贡献巨大。',
    description:
      '公元25年，西汉皇室后裔刘秀在绿林赤眉起义中崛起，推翻了王莽的新朝，重建了汉朝，定都洛阳，史称东汉。东汉延续了西汉的强盛，但中央集权逐渐被外戚和宦官专权所侵蚀。\n\n东汉时期最重要的科技成就是造纸术的改进。公元105年，宦官蔡伦总结前人的经验，用树皮、麻头、破布、旧渔网等廉价原料制造出了质量更高、成本更低的纸张。他将此法上奏汉和帝，得到推广，天下人称之为"蔡侯纸"。\n\n在纸发明之前，中国人用龟甲兽骨、青铜器、竹简木牍、丝绸等材料书写。竹简太笨重，丝绸太昂贵，都不利于知识的传播。造纸术的发明是人类书写材料的一次革命——纸张轻便、廉价、便于书写和携带，极大地促进了文化的积累和传播。\n\n造纸术后来通过阿拉伯人传到了欧洲，对世界文明的发展产生了不可估量的影响。如果没有纸，文艺复兴、宗教改革、科学革命都难以想象。造纸术与印刷术、火药、指南针一起，被称为中国古代四大发明，是中国对人类文明最伟大的贡献之一。',
    imageEra: 'classical',
    relatedNodeIds: ['han-dynasty', 'yellow-turban'],
