    description:
      '公元184年，张角领导的黄巾起义爆发。起义军以黄巾裹头，高喊"苍天已死，黄天当立，岁在甲子，天下大吉"的口号，在全国范围内同时发动，声势浩大。虽然起义在短短几个月内就被镇压下去，但东汉王朝已经元气大伤，名存实亡。\n\n黄巾起义的背景是东汉后期的深刻社会危机：外戚宦官交替专权，政治腐败黑暗；土地兼并严重，大量农民失去土地，流离失所；加上连年的自然灾害，瘟疫流行，民不聊生。张角创立了"太平道"，以传教和治病的方式组织民众，十余年间聚集了数十万信徒。\n\n在镇压黄巾起义的过程中，各地州牧豪强趁机扩充实力，形成了军阀割据的局面。董卓入京、袁绍曹操等十八路诸侯讨董……东汉末年的大乱世拉开了帷幕。\n\n这个乱世孕育了无数英雄人物，也成为中国文学最钟爱的题材之一。元末明初罗贯中根据这段历史创作的《三国演义》，成为中国四大名著之一，"桃园结义""三顾茅庐""赤壁之战"等故事家喻户晓。三国时代是中国人英雄情怀和智谋文化的重要源头。',
    imageEra: 'classical',
    relatedNodeIds: ['eastern-han', 'three-kingdoms'],
