    description:
      '公元220年，曹操之子曹丕逼迫汉献帝禅位，建立魏国，定都洛阳，东汉正式灭亡。次年（221年），刘备在成都称帝，建立蜀汉；229年，孙权在建业（今南京）称帝，建立吴国。魏、蜀、吴三国鼎立的局面正式形成。\n\n三国时代虽然只有短短几十年（220-280年），但它是中国历史上最具传奇色彩的时代之一。这是一个英雄辈出、群星璀璨的时代：曹操的雄才大略、诸葛亮的智慧忠诚、关羽的义勇双全、张飞的勇猛直率、周瑜的儒将风度、司马懿的隐忍谋略……无数鲜活的人物形象通过《三国演义》深入人心。\n\n三国之间的战争和外交，充满了精彩的谋略和经典的战役：官渡之战、赤壁之战、夷陵之战，都是中国战争史上的经典战例。诸葛亮的"隆中对"为刘备规划了三分天下的战略蓝图，"草船借箭""空城计"等故事虽未必全是史实，但早已成为中国文化的一部分。\n\n三国时代也是一个技术和制度创新的时代。诸葛亮发明了连弩和木牛流马（一种运输工具）；曹魏推行屯田制，解决了军粮问题；吴国发展海上交通，派人到达了夷洲（今台湾）。三国虽然短暂，但其文化影响深远而持久。',
    imageEra: 'classical',
    relatedNodeIds: ['yellow-turban', 'western-jin'],
