    eraId: 'classical',
    location: { lat: 45.5, lng: 9.2 },
    summary: '罗马皇帝君士坦丁颁布米兰敕令，基督教合法化。',
    description:
      '公元313年，罗马皇帝君士坦丁一世与李锡尼共同颁布了《米兰敕令》（Edict of Milan），宣布基督教在罗马帝国境内合法化，并归还此前没收的教会财产。这是基督教历史上的转折点——从一个受迫害的地下宗教，变成了帝国境内合法的、甚至日渐尊贵的宗教。\n\n在此之前的近三百年里，基督教在罗马帝国长期处于非法地位，信徒屡遭迫害。尼禄皇帝将罗马大火的罪责推给基督徒，开始了第一次大规模迫害。此后，图密善、图拉真、马可·奥勒留、戴克里先等皇帝都曾下令迫害基督徒。许多信徒被处以极刑，成为殉道者。然而，迫害不仅没有消灭基督教，反而使其更加壮大——殉道者的勇气和虔诚吸引了更多人皈依。\n\n君士坦丁本人在临终前正式受洗成为基督徒。他还将首都从罗马迁到拜占庭，并将其改名为君士坦丁堡（今土耳其伊斯坦布尔）。公元380年，狄奥多西一世进一步将基督教定为罗马帝国的国教。\n\n基督教的合法化和国教化深刻改变了罗马帝国，也改变了整个西方世界的历史进程。教会成为帝国中最强大的组织之一，在西罗马帝国灭亡后的混乱年代里，是教会保存了古典文化的火种，并逐步将日耳曼各族纳入基督教世界。',
    imageEra: 'classical',
    relatedNodeIds: ['jesus', 'rome-split'],
