    categories: ['military', 'politics'],
    type: 'event',
    eraId: 'classical',
    location: { lat: 35, lng: 110 },
    summary: '匈奴、鲜卑、羯、氐、羌五族入主中原，西晋灭亡。',
    description:
      '公元316年，匈奴族建立的汉赵政权攻破长安，俘虏晋愍帝，西晋灭亡。此后一百多年间，中国北方陷入了空前的混乱，匈奴、鲜卑、羯、氐、羌五个少数民族（合称"五胡"）纷纷建立政权，互相攻伐，史称"五胡乱华"或"五胡十六国"时期。\n\n这是中国历史上最黑暗的时期之一。北方长期战乱，人口锐减，经济遭到严重破坏。各族政权更迭频繁，最短的只有几年。羯人石勒建立的后赵、氐人苻坚建立的前秦、鲜卑慕容氏建立的前燕，都曾一度统一北方，但都很快分崩离析。\n\n然而，这也是一个民族大融合的时代。内迁的少数民族在与汉族的杂居中逐渐汉化——他们采用汉族的制度，学习汉族的文化，与汉族通婚。北魏孝文帝的改革就是这种汉化趋势的高峰：他将都城从平城（今山西大同）迁到洛阳，下令鲜卑贵族改汉姓、穿汉服、说汉语、与汉族通婚。\n\n与此同时，大批北方汉人南迁，将中原先进的文化和技术带到了江南，促进了南方经济的开发。南方的东晋和随后的宋齐梁陈（南朝）保持了汉族文化的传承。北朝的民族融合和南朝的经济文化发展，为后来隋唐大一统盛世奠定了基础。',
    imageEra: 'classical',
