    summary: '穆罕默德在麦加传教，希吉拉纪元开始，伊斯兰教兴起。',
    description:
      '公元622年，伊斯兰教创始人穆罕默德（Muhammad）带领信徒从麦加迁徙到麦地那，这一事件被称为"希吉拉"（Hijra，意为迁徙），伊斯兰历由此开始。伊斯兰教是世界三大宗教之一，"伊斯兰"意为"顺从（真主的意志）"。\n\n穆罕默德大约生于公元570年，40岁时开始在麦加传教。他宣称受到天使吉卜利勒（加百列）的启示，号召人们信仰唯一的真主安拉，反对多神崇拜和偶像崇拜。他的传教遭到了麦加贵族的强烈反对和迫害，因为这威胁到了麦加作为多神教朝圣中心的经济利益。\n\n迁徙到麦地那后，穆罕默德建立了一个以宗教为纽带的政教合一的社团（乌玛），并逐渐发展壮大。经过多年的战争和谈判，穆罕默德最终和平征服了麦加，清除了克尔白神殿中的偶像，将其改为伊斯兰教的圣地。到632年穆罕默德去世时，阿拉伯半岛基本上统一在伊斯兰教的旗帜下。\n\n伊斯兰教的经典是《古兰经》，被穆斯林认为是真主安拉通过穆罕默德传达给人类的启示。五大功课（念证词、礼拜、斋戒、天课、朝觐）是穆斯林的基本宗教义务。此后，伊斯兰教以惊人的速度传播，在短短一百多年内，从阿拉伯半岛的一个地方宗教发展成为横跨欧亚非三大洲的世界性宗教，建立了庞大的阿拉伯帝国。',
