    summary: '中国历史上唯一的女皇帝武则天登基，改国号为周。',
    description:
      '公元690年，武则天正式称帝，改国号为"周"，定都洛阳，称"神都"。她是中国历史上唯一的正统女皇帝，也是即位年龄最大的皇帝之一（67岁即位）。\n\n武则天的一生充满了传奇色彩。她原本是唐太宗的才人，太宗死后入感业寺为尼，后被唐高宗李治接入宫中，逐步晋升为皇后。高宗体弱多病，武则天逐渐参与朝政，与高宗并称"二圣"。高宗死后，她先后废掉两个儿子（中宗和睿宗），最终自己登上皇位。\n\n武则天是一位极具政治才能的统治者。她打击门阀士族势力，大力推行科举制，开创了殿试和武举，广泛选拔人才；她重视农业生产，轻徭薄赋，社会经济持续发展；她设立铜匦（检举箱），鼓励告密，重用酷吏，以恐怖手段对付反对者，但也有知人善任的一面——狄仁杰、张柬之、姚崇、宋璟等名臣都得到过她的重用。\n\n武则天的统治上承"贞观之治"，下启"开元盛世"，为唐朝的鼎盛奠定了基础。公元705年，武则天病重，宰相张柬之等人发动政变，逼她退位，中宗复位，恢复唐朝国号。同年，武则天去世，立"无字碑"——功过是非留待后人评说。作为中国历史上唯一的女皇帝，她的存在本身就是对传统男权社会的巨大挑战和突破。',
