    type: 'event',
    eraId: 'industrial',
    location: { lat: 50.7, lng: 4.4 },
    summary: '拿破仑在滑铁卢战败，拿破仑帝国终结，维也纳体系建立。',
    important: true,
    description:
      '公元1815年6月18日，拿破仑率领的法军与英国威灵顿公爵和普鲁士布吕歇尔元帅率领的反法同盟联军，在比利时小镇滑铁卢展开决战。法军战败，拿破仑的百日王朝终结。这是拿破仑军事生涯的最后一战，"滑铁卢"从此成为失败的代名词。\n\n滑铁卢战役的背景是拿破仑的"百日王朝"——1815年3月，拿破仑从被流放的厄尔巴岛逃回法国，受到军队和民众的热烈欢迎，路易十八仓皇出逃，拿破仑重新登上皇位。欧洲各国迅速组成第七次反法同盟，集结了重兵。拿破仑决定先发制人，各个击破。\n\n滑铁卢战役打得异常惨烈。双方伤亡都很惨重。关键时刻，普鲁士军队及时赶到，增援威灵顿的英军，而拿破仑期待的格鲁希元帅的法军却迟迟没有出现。法军腹背受敌，全线崩溃。拿破仑退位后被流放到南大西洋的圣赫勒拿岛，于1821年在那里去世。\n\n滑铁卢战役结束了拿破仑时代，也结束了法国大革命以来二十多年的欧洲战乱。随后召开的维也纳会议重新划分了欧洲的政治版图，建立了所谓的"维也纳体系"——欧洲列强之间的势力均衡。这套体系维持了欧洲约一百年的总体和平（虽然局部战争不断），直到第一次世界大战爆发才彻底瓦解。\n\n十九世纪是欧洲的"百年和平"，也是欧洲经济、科技、文化全面领先世界的世纪——工业革命深入发展，殖民扩张达到顶峰，科学发现和技术发明层出不穷。这个世纪塑造了现代世界的基本面貌。',
