    eraId: 'industrial',
    location: { lat: 22.3, lng: 113.6 },
    summary: '鸦片战争爆发，中国近代史的开端，百年屈辱的开始。',
    description:
      '公元1839年，林则徐到广州禁烟，在虎门销毁了两万多箱鸦片。英国以此为借口，发动了侵略中国的鸦片战争（1840-1842年）。战争以清政府的惨败告终，1842年，中英签订了中国近代史上第一个不平等条约——《南京条约》。鸦片战争是中国近代史的开端，也是中国百年屈辱史的起点。\n\n鸦片战争的深层原因是中英之间的贸易失衡。长期以来，中国向英国出口大量的茶叶、丝绸、瓷器，而英国的工业品在中国几乎没有市场，中英贸易中英国长期处于逆差地位。为了扭转贸易逆差，英国开始向中国大量走私鸦片。鸦片的泛滥不仅严重损害了中国人的身心健康，也导致中国白银大量外流，财政状况恶化。\n\n《南京条约》的主要内容包括：割让香港岛给英国，开放广州、厦门、福州、宁波、上海五处为通商口岸，赔款2100万银元，协定关税等。此后，美国、法国等列强也趁火打劫，迫使清政府签订了一系列不平等条约。\n\n鸦片战争打碎了清朝"天朝上国"的迷梦。一个曾经辉煌的古老帝国，在西方的坚船利炮面前不堪一击。这一震惊促使一部分中国人开始睁眼看世界，探索救国救民的道路——林则徐、魏源提出了"师夷长技以制夷"的主张。此后的一百多年里，中国人民在屈辱中奋起，在黑暗中求索，经历了洋务运动、戊戌变法、辛亥革命、新文化运动，最终走上了革命和复兴的道路。鸦片战争是中国近代史上最深的一道伤疤，也是中华民族觉醒的起点。',
    imageEra: 'industrial',
    relatedNodeIds: ['qing-dynasty', 'sino-japanese-war'],
    important: true,
