    title: '甲午战争',
    year: 1895,
    yearDisplay: '公元1895年',
    civilization: 'china',
    categories: ['military', 'politics'],
    type: 'event',
    eraId: 'industrial',
    location: { lat: 39, lng: 122 },
    summary: '中日甲午战争，清朝战败，《马关条约》签订，民族危机空前加深。',
    description:
      '公元1894年（甲午年），日本发动了侵略中国和朝鲜的战争，史称"甲午中日战争"。清朝军队在陆海两线都遭遇惨败。1895年，清政府被迫与日本签订《马关条约》。这是中国近代史上最屈辱的条约之一，也标志着中华民族的民族危机空前加深。\n\n《马关条约》的主要内容包括：中国承认朝鲜完全独立（实际上是承认日本对朝鲜的控制）；割让辽东半岛、台湾全岛及所有附属岛屿、澎湖列岛给日本；赔偿日本军费白银二亿两；开放沙市、重庆、苏州、杭州为通商口岸；允许日本在中国通商口岸开设工厂。\n\n甲午战争的失败给中国人带来了巨大的心理震撼。在此之前，中国人虽然被西方列强打败过，但多少还有些安慰——西方是"夷狄"，船坚炮利而已。但这一次，竟然被一个一直被中国人看不起的"蕞尔小邦"日本打败了，而且败得如此之惨——北洋水师全军覆没，陆军也节节败退。\n\n痛定思痛，中国人意识到，仅仅学习西方的技术（洋务运动）是不够的，必须进行制度变革。于是，以康有为、梁启超为代表的维新派登上历史舞台，发动了"戊戌变法"（1898年），试图在中国建立君主立宪制度。虽然变法只持续了一百零三天就失败了（因此又称"百日维新"），但它开启了中国政治制度现代化的尝试。甲午战争是中国近代史上的一个重要转折点——从器物层面的改革深入到了制度层面的变革。',
