    type: 'event',
    eraId: 'modern',
    location: { lat: 50, lng: 10 },
    summary: '杜鲁门主义出台，美苏冷战开始，世界进入两极格局。',
    description:
      '公元1947年3月12日，美国总统杜鲁门在国会发表演说，提出了以"遏制共产主义"为核心的对外政策，这就是著名的"杜鲁门主义"。杜鲁门主义的出台标志着美苏冷战的正式开始。此后近半个世纪里，世界被划分为以美国为首的资本主义阵营和以苏联为首的社会主义阵营，两极格局成为国际关系的基本特征。\n\n"冷战"（Cold War）一词形象地描述了这场对峙的特点——虽然两大阵营之间的矛盾极其尖锐，但由于核武器的存在，双方都不敢直接发动战争（热战），只能进行政治、经济、军事、文化、意识形态等各方面的对抗和竞争。\n\n冷战的主要表现包括：政治上，两大阵营对立，美国推行马歇尔计划援助西欧，苏联成立共产党和工人党情报局；军事上，北约（1949年）和华约（1955年）两大军事集团对峙，军备竞赛不断升级，核武库膨胀到足以毁灭人类几十次的程度；经济上，两个平行的市场体系对立；意识形态上，自由民主与社会主义之争遍及全球。\n\n冷战不是完全没有热战——朝鲜战争、越南战争、阿富汗战争等"代理人战争"此起彼伏，造成了巨大的人员伤亡和破坏。古巴导弹危机（1962年）更是把人类带到了核战争的边缘。冷战持续了近半个世纪，直到1991年苏联解体才宣告结束。冷战深刻塑造了二十世纪后半叶的世界格局，也留下了深远的影响——今天的许多国际问题，仍然可以看到冷战的影子。',
