    id: 'korean-war',
    title: '朝鲜战争',
    year: 1950,
    yearDisplay: '公元1950年',
    civilization: 'eastAsia',
    categories: ['military'],
    type: 'event',
    eraId: 'modern',
    location: { lat: 38, lng: 127 },
    summary: '朝鲜战争爆发，冷战中的第一场热战。',
    description:
      '公元1950年6月25日，朝鲜人民军越过三八线向南进攻，朝鲜战争爆发。美国操纵联合国安理会通过决议，组成"联合国军"干涉朝鲜战争。战火烧到了中朝边境的鸭绿江边。1950年10月，中国人民志愿军跨过鸭绿江，抗美援朝，保家卫国。\n\n朝鲜战争是冷战中的第一场大规模"热战"，也是二战后第一场重要的局部战争。战争的双方是朝鲜和中国（有苏联的支持）对以美国为首的"联合国军"（包括英国、加拿大、澳大利亚、土耳其等16个国家的军队）。战争打了三年，双方在三八线附近拉锯，伤亡都很惨重。\n\n1953年7月27日，交战双方在板门店签署了《朝鲜停战协定》，战争结束。然而，严格来说，朝鲜战争至今没有正式结束——只有停战协定，没有和平条约。朝鲜半岛至今仍处于分裂状态，南北双方对峙，是世界上军事部署最密集的地区之一。\n\n朝鲜战争对中国的意义尤为重大。新中国成立刚刚一年，百废待兴，但中国人民志愿军在装备落后、后勤困难的条件下，硬是把世界上最强大的美军从鸭绿江边打回到了三八线。这场战争打出了新中国的国威和军威，打破了美军不可战胜的神话，极大地提高了中国的国际地位和民族自信心。彭德怀元帅说："西方侵略者几百年来只要在东方一个海岸上架起几尊大炮就可霸占一个国家的时代是一去不复返了。"抗美援朝精神至今仍是中国人民宝贵的精神财富。',
