    id: 'sputnik',
    title: '斯普特尼克一号与太空时代',
    year: 1957,
    yearDisplay: '公元1957年',
    civilization: 'europe',
    categories: ['science'],
    type: 'dynasty',
    eraId: 'modern',
    location: { lat: 55.8, lng: 37.6 },
    summary: '苏联发射人类第一颗人造地球卫星，太空时代开启。',
    description:
      '公元1957年10月4日，苏联成功发射了人类第一颗人造地球卫星——斯普特尼克一号（Sputnik 1，俄语意为"卫星"、"旅伴"）。这颗直径约58厘米、重约83公斤的金属球，在太空中发出"嘟嘟嘟"的无线电信号，绕地球飞行了三个多月。它的发射标志着人类太空时代的正式开始。\n\n斯普特尼克一号的发射在西方世界引起了巨大的震动和恐慌。一向自认为科技领先的美国，竟然被苏联在太空竞赛中抢先了一步。"斯普特尼克危机"促使美国政府加大了对科技和教育的投入，NASA（美国航空航天局）随即成立。美苏之间的太空竞赛全面展开。\n\n此后短短十几年里，太空探索取得了令人眼花缭乱的成就：1961年，苏联宇航员加加林成为第一个进入太空的人类；1963年，苏联女宇航员捷列什科娃成为第一位进入太空的女性；1965年，人类首次太空行走；1969年，美国阿波罗11号成功将人类送上月球；太空站、航天飞机、火星探测器、哈勃太空望远镜……一个个太空梦想变成了现实。\n\n太空探索不仅是超级大国竞争的竞技场，更是人类好奇心和探索精神的体现。当人类第一次从太空回望自己的星球，看到一颗蔚蓝的星球悬挂在漆黑的宇宙中，这种体验深刻改变了人类对自身和地球的认知——我们都是"地球号"太空船上的乘客。太空时代让人类的视野第一次真正超越了地球的边界。',
    imageEra: 'modern',
    relatedNodeIds: ['gagarin', 'apollo-11'],
    important: true,
