    summary: '美苏在古巴部署导弹问题上对峙，人类最接近核战争的时刻。',
    important: true,
    description:
      '公元1962年10月，一场惊心动魄的危机——古巴导弹危机——将人类带到了核战争的边缘。这是冷战期间美苏之间最严重的一次正面对抗，也是人类历史上最接近核毁灭的时刻。\n\n危机的起因是苏联在美国的后院——古巴——部署核导弹。1959年，卡斯特罗领导的古巴革命取得胜利，古巴走上了社会主义道路，与苏联结盟。美国曾试图武装入侵古巴（猪湾事件），但失败了。为了保护古巴，也为了改变美苏核力量的不平衡（当时美国在苏联周边部署了大量核导弹，而苏联能打到美国本土的洲际导弹数量很少），赫鲁晓夫决定秘密在古巴部署中程核导弹。\n\n美国U-2侦察机发现了苏联在古巴部署的导弹阵地。肯尼迪总统决定对古巴实施海上封锁。十三天里，全世界都屏住了呼吸——美国的军舰和苏联的载有核弹头的潜艇在加勒比海对峙，战争一触即发。双方的核武库都已经高度戒备，只要有人误判或失控，核战争就会爆发。\n\n最终，在双方的外交斡旋下，危机以妥协收场：苏联同意撤走在古巴的导弹，美国承诺不入侵古巴，并秘密撤走在土耳其的导弹。古巴导弹危机让双方领导人都意识到了核战争的危险性——那将是没有赢家的战争。此后，美苏建立了热线（直接沟通渠道），开始进行核裁军谈判。但人类头上的核达摩克利斯之剑，至今仍然高悬。',
