    id: 'apollo-11',
    title: '阿波罗11号登月',
    year: 1969,
    yearDisplay: '公元1969年',
    civilization: 'america',
    categories: ['science'],
    type: 'event',
    eraId: 'modern',
    location: { lat: 0.67, lng: 23.47 },
    summary: '人类首次登上月球，阿姆斯特朗迈出「个人的一小步，人类的一大步」。',
    description:
      '公元1969年7月20日，美国"阿波罗11号"宇宙飞船的登月舱在月球表面的静海成功着陆。宇航员尼尔·阿姆斯特朗（Neil Armstrong）成为第一个踏上月球的人类。他说出了那句著名的话："这是个人的一小步，却是人类的一大步。"（That is one small step for man, one giant leap for mankind.）\n\n阿波罗11号的成功登月，是人类太空探索史上最伟大的成就，也是二十世纪最激动人心的科学壮举。从1957年斯普特尼克一号发射到人类登上月球，只用了短短的12年。太空竞赛的紧迫感和巨大投入，催生了惊人的技术进步。\n\n阿波罗计划是一项巨大的系统工程——它动员了约40万人，两万多家企业和大学参与，耗资约250亿美元（相当于今天的两千多亿美元）。整个阿波罗系列共进行了11次载人飞行，其中6次成功登月，12名宇航员踏上了月球表面。最后一次登月是1972年的阿波罗17号，此后再也没有人登上过月球。\n\n登月的照片和视频震撼了全世界。当人类从月球上回望地球——一颗悬挂在漆黑太空中的蓝色弹珠——那种视觉冲击是前所未有的。著名的"蓝色弹珠"照片成为环保运动的标志，也让人类前所未有地意识到我们只有一个地球。阿波罗登月不仅是科学和工程的胜利，更是人类探索精神和梦想力量的永恒象征。',
    imageEra: 'modern',
