    id: 'reform-and-opening',
    title: '中国改革开放',
    year: 1978,
    yearDisplay: '公元1978年',
    civilization: 'china',
    categories: ['politics', 'science'],
    type: 'event',
    eraId: 'modern',
    location: { lat: 22.5, lng: 114.1 },
    summary: '十一届三中全会召开，改革开放政策启动，中国经济腾飞。',
    description:
      '公元1978年12月，中国共产党十一届三中全会在北京召开，确立了解放思想、实事求是的思想路线，作出了把党和国家工作重心转移到经济建设上来、实行改革开放的历史性决策。这是中国现代史上的伟大转折，标志着中国进入了改革开放和社会主义现代化建设的新时期。\n\n改革开放是从农村开始的。安徽凤阳小岗村的农民偷偷搞起了"大包干"（家庭联产承包责任制），极大地调动了农民的生产积极性，粮食产量大幅提高。此后，改革从农村推向城市，从经济体制改革推向全面深化改革。对外开放同样精彩——深圳、珠海、汕头、厦门四个经济特区的设立，打开了中国与世界交流的窗口。\n\n四十多年来，中国的改革开放取得了举世瞩目的伟大成就。中国经济持续快速增长，GDP总量跃居世界第二。数亿人摆脱了贫困，创造了人类减贫史上的奇迹。人民生活水平显著提高，从温饱不足到全面小康。基础设施建设突飞猛进，高速公路、高速铁路、港口、机场规模均居世界前列。科技创新能力大幅提升，在载人航天、高铁、5G通信、人工智能、新能源等领域达到世界先进水平。\n\n改革开放是决定当代中国命运的关键抉择，也是实现中华民族伟大复兴的必由之路。四十多年的实践证明，改革开放是中国发展的根本动力，也是中国走向世界、融入世界的必由之路。中国的改革开放仍在进行中，全面深化改革和扩大开放将继续为中国的发展提供强大动力，也将为世界经济增长做出更大贡献。',
