    description:
      '2010年前后，随着智能手机的普及和3G/4G网络的大规模建设，人类进入了移动互联网时代。互联网不再只存在于电脑里，而是装进了每个人的口袋，随时随地可以连接。这是继桌面互联网之后的又一次信息革命浪潮，对人类生活的影响甚至更加深刻。\n\n2007年苹果公司推出的iPhone是移动互联网时代的标志性产品——多点触控、应用商店、移动浏览器，重新定义了智能手机的形态。此后，谷歌的安卓系统迅速占领了更大的市场份额。手机不再只是打电话的工具，它变成了钱包、相机、音乐播放器、游戏机、导航仪、办公助手……\n\n移动互联网催生了全新的商业模式和生活方式：移动支付让出门不用带钱包；网约车、外卖改变了城市生活；社交媒体让人与人的连接更加紧密，也让信息传播的速度和规模前所未有；短视频和直播改变了内容生产和消费的形态；在线教育、远程医疗、云办公……移动互联网正在渗透到生活的每一个角落。\n\n中国在移动互联网时代走在了世界前列。中国移动支付的普及率、移动电商的规模、即时通讯的活跃度都位居世界第一。以BAT（百度、阿里巴巴、腾讯）和后来的字节跳动、拼多多等为代表的互联网企业，在商业模式创新和用户体验方面甚至领先于硅谷。移动互联网正在深刻改变中国的经济结构和社会形态，也让中国人的生活方式发生了翻天覆地的变化。',
