    description: `拜占庭帝国即东罗马帝国，395年罗马帝国分裂后东部延续，1453年被奥斯曼帝国攻陷君士坦丁堡后灭亡。它延续了近1100年，横跨整个中世纪，是欧洲历史最悠久的君主制国家，对欧洲、近东和俄罗斯的文明发展产生了不可估量的影响。

395年，罗马皇帝狄奥多西一世去世，帝国正式分裂为东西两部分。西罗马帝国在蛮族冲击下于476年灭亡，而东罗马帝国（因其首都君士坦丁堡原名拜占庭，后世历史学家称之为"拜占庭帝国"，但当时的居民始终自称"罗马人"）则延续了千年之久。

拜占庭帝国的历史大致可分为几个时期：

**1. 早期拜占庭（4-7世纪）：从晚期罗马到希腊化转型**
这一时期帝国仍以罗马帝国的继承者自居，疆域辽阔，包括巴尔干、安纳托利亚、叙利亚、巴勒斯坦、埃及和北非。最辉煌的是查士丁尼一世（Justinian I，527-565年在位）时期——他雄心勃勃地试图恢复罗马帝国的全盛版图，派大将贝利撒留和纳尔塞斯先后收复了意大利、北非和西班牙南部。查士丁尼下令编纂的《查士丁尼法典》（Corpus Juris Civilis）是罗马法的集大成之作，也是后世大陆法系最重要的渊源之一。他还下令修建了宏伟的圣索菲亚大教堂（Hagia Sophia，537年建成），是拜占庭建筑艺术的巅峰之作，其巨大的穹顶在当时被视为工程奇迹。

**2. 中期拜占庭（7-12世纪）：希腊化与黄金时代**
7世纪，阿拉伯帝国崛起，夺走了拜占庭最富庶的叙利亚、巴勒斯坦和埃及行省。帝国虽然领土缩小，但反而更加凝聚——以希腊语为官方语言，以东正教为精神核心，完成了从"罗马帝国"向"希腊化东正教帝国"的转型。马其顿王朝（867-1056年）是拜占庭的黄金时代，经济繁荣，文化昌盛，军事上收复了部分失地，君士坦丁堡人口达到约50-80万，是当时欧洲最大的城市。这一时期拜占庭还积极向北方传教——西里尔和美多迪乌斯兄弟向斯拉夫人传教，创造了西里尔字母，深刻影响了俄罗斯和东欧文明。

**3. 晚期拜占庭（12-15世纪）：衰落与灭亡**
1071年，塞尔柱突厥人在曼齐克特战役中大败拜占庭军队，夺取了安纳托利亚大部——这是帝国衰落的转折点。此后虽然经历了科穆宁王朝的短暂复兴，但1204年第四次十字军东征洗劫了君士坦丁堡，对帝国造成了致命打击。此后拜占庭一蹶不振，领土不断被奥斯曼土耳其蚕食。1453年5月29日，奥斯曼苏丹穆罕默德二世率军攻陷君士坦丁堡，末代皇帝君士坦丁十一世身着甲胄战死沙场，延续千年的拜占庭帝国正式灭亡。

拜占庭帝国的文化遗产极其丰厚：
- 宗教方面：拜占庭是东正教的中心，东正教通过拜占庭传播到了巴尔干和俄罗斯地区，深刻影响了东欧文明的走向。今天俄罗斯、保加利亚、塞尔维亚等国的宗教和文化传统都源于拜占庭。
- 法律方面：《查士丁尼法典》是罗马法最系统的汇编，对后世西方法律体系的形成影响深远。
- 艺术与建筑方面：拜占庭风格的教堂（中心穹顶、马赛克镶嵌画、金色背景）、圣像画、手抄本插图等，对东欧和俄罗斯艺术影响极大。
- 知识传承方面：拜占庭保存了大量古希腊罗马的典籍和文化，这些知识后来通过意大利人文主义者回流到西欧，推动了文艺复兴的兴起。

可以说，拜占庭帝国是连接古典文明与近代欧洲的桥梁，也是东方与西方文明交流的十字路口。`,
