    location: { lat: 50.9, lng: 6.9 },
    summary: '查理曼建立的西欧大帝国，800年加冕为罗马人的皇帝，843年三分帝国形成法德意雏形。',
    description: `查理曼帝国（Carolingian Empire，约751-843年）是中世纪早期西欧最强大的国家，由法兰克王国的加洛林王朝建立。它在查理曼大帝（Charlemagne，即查理一世）统治时期达到鼎盛，疆域覆盖了今天的法国、德国、瑞士、奥地利、荷兰、比利时、卢森堡以及意大利北部和西班牙北部的部分地区，几乎重现了西罗马帝国在西欧的版图。800年，查理曼被教皇利奥三世加冕为"罗马人的皇帝"，标志着他成为了西欧的最高统治者。

加洛林王朝的崛起始于查理·马特（Charles Martel，"铁锤查理"，714-741年在位）。他是法兰克王国墨洛温王朝的宫相（类似首相），实际掌握着国家权力。732年，他率领法兰克军队在普瓦捷战役（又称图尔战役）中击败了入侵西欧的阿拉伯军队，阻止了伊斯兰势力向欧洲的进一步扩张，挽救了基督教欧洲。这场战役被认为是世界历史上最重要的战役之一。

查理·马特的儿子丕平三世（Pepin the Short，矮子丕平）在751年推翻了墨洛温王朝的最后一位国王，建立了加洛林王朝。丕平三世还与教皇结成了联盟——他出兵意大利，击败了伦巴第人，并将意大利中部的土地赠送给教皇，这就是"丕平献土"，奠定了教皇国的基础。作为回报，教皇为丕平加冕，赋予了加洛林王朝神圣的合法性。

查理曼（768-814年在位）是丕平三世的儿子，也是加洛林王朝最伟大的君主。他在位46年，发动了50多次战争，大大扩张了法兰克王国的版图：
- 征服了伦巴第王国（意大利北部），自封为"伦巴第国王"。
- 对萨克森人进行了长达30年的残酷战争，最终迫使萨克森人皈依基督教并并入法兰克王国。
- 击败了多瑙河流域的阿瓦尔人，将巴伐利亚和卡林西亚纳入版图。
- 入侵西班牙，从阿拉伯人手中夺取了巴塞罗那地区，建立了"西班牙边区"。

到800年，查理曼的帝国已经成为西欧自罗马帝国灭亡以来最强大的国家。就在这一年的圣诞节，教皇利奥三世在罗马圣彼得大教堂为查理曼加冕，宣布他为"罗马人的皇帝"（Imperator Romanorum）。这一事件具有深远的象征意义——它标志着西欧重新有了一个"罗马皇帝"，也标志着教会与世俗权力的结盟（教权与王权的二元政治结构从此成为中世纪欧洲的基本特征）。

查理曼不仅是伟大的军事家，也是杰出的统治者和文化赞助人。他建立了高效的行政体系：将帝国分为数百个郡，由伯爵管理；设立了"巡按使"（Missi Dominici）制度，由国王的特使定期巡视地方，监督官员；每年召开"春季大会"，召集贵族和主教共商国是。他还统一了货币和法律，促进了贸易和经济发展。

**加洛林文艺复兴**是查理曼时代最重要的文化成就。查理曼本人虽然识字不多（据说他直到晚年还在练习写字），但他非常重视教育和文化。他邀请了欧洲各地的学者来到他的宫廷，其中最著名的是英国学者阿尔昆。他们兴办学校、抄写古籍、改革文字（发明了清晰易读的加洛林小写字母，这是现代拉丁字母的基础）、整理和保存了大量古典文献——许多古希腊罗马的著作就是通过加洛林时期的抄本才得以流传后世的。虽然加洛林文艺复兴的规模无法与意大利文艺复兴相比，但它在"黑暗时代"的欧洲点亮了文化的明灯，为后来的欧洲文明奠定了基础。

查理曼于814年去世，享年72岁。他的儿子虔诚者路易（Louis the Pious）继承了皇位，但路易缺乏政治才能，帝国很快陷入内乱。843年，查理曼的三个孙子签订了《凡尔登条约》，将帝国一分为三：
- **西法兰克王国**（大致相当于今天的法国），由秃头查理统治，后来发展为法兰西王国。
- **东法兰克王国**（大致相当于今天的德国），由日耳曼人路易统治，后来发展为神圣罗马帝国。
- **中法兰克王国**（北起荷兰，南至意大利北部，包括洛林和勃艮第），由长子洛泰尔统治，并承袭了皇帝头衔。

《凡尔登条约》奠定了近代法国、德国和意大利三国版图的雏形。查理曼帝国虽然只存在了不到100年，但它对欧洲历史的影响是深远的——它将西欧大部分地区统一在一个政权之下，传播了基督教和古典文化，塑造了中世纪欧洲的基本面貌。查理曼被视为法国和德国共同的祖先，也是欧洲统一理念的象征之一。`,
