    summary: '以德意志为核心的中世纪欧洲帝国，奥托一世加冕称帝，伏尔泰评价"既不神圣、也不罗马、更非帝国"，1806年被拿破仑解散。',
    description: `神圣罗马帝国（962-1806年）是中世纪和近代欧洲的一个重要政治实体，以"罗马"和"帝国"为名，但其实际形态与古罗马帝国相去甚远。法国启蒙思想家伏尔泰曾辛辣地评价它："既不神圣，也不罗马，更非帝国"——这一评价虽有夸张，却也道出了神圣罗马帝国的特殊性：它不是一个中央集权的统一国家，而是一个由数百个邦国、领地、自由城市和教会领地组成的松散政治联合体。

神圣罗马帝国的前身是东法兰克王国。962年，德意志国王奥托一世（Otto I，"奥托大帝"）在罗马被教皇约翰十二世加冕为"罗马人的皇帝"，神圣罗马帝国正式建立。这一事件标志着"君权神授"观念的延续——德意志国王自认为是古罗马帝国和查理曼帝国的继承者，是基督教世界的世俗领袖。

神圣罗马帝国的历史大致可分为几个时期：

**1. 奥托王朝与萨利安王朝（10-12世纪）：皇权鼎盛期**
这一时期皇帝的权力较大，控制着德意志和意大利北部，与教皇之间既有合作也有斗争。最著名的是"叙任权之争"——皇帝亨利四世与教皇格列高利七世争夺主教任命权，亨利四世被迫在卡诺莎城堡前赤足冒雪向教皇请罪三天，这就是著名的"卡诺莎之辱"。这场斗争最终以双方妥协告终，但预示着皇权与教权的长期较量。

**2. 霍亨斯陶芬王朝（12-13世纪）：与教皇斗争加剧**
腓特烈一世（"红胡子"巴巴罗萨）和腓特烈二世时期，帝国与教皇的斗争白热化。为了争夺意大利，皇帝耗费了大量国力，而德意志境内的诸侯势力则趁机坐大。

**3. 大空位时期与选帝侯制度（13-14世纪）：皇权衰落**
1254-1273年出现了"大空位时期"——没有公认的皇帝，诸侯割据严重。1356年，查理四世颁布了《金玺诏书》，正式确立了"选帝侯"制度——皇帝由七位选帝侯（三位教会选帝侯：美因茨、科隆、特里尔大主教；四位世俗选帝侯：萨克森公爵、勃兰登堡藩侯、莱茵-普法尔茨伯爵、波希米亚国王）选举产生。这一制度虽然稳定了继承秩序，但也大大削弱了皇权。

**4. 哈布斯堡王朝（15-19世纪）：帝国的黄昏**
从15世纪中期开始，哈布斯堡家族几乎垄断了皇位（通过联姻和贿赂，他们几乎每次都能当选）。哈布斯堡家族的统治重心逐渐转向自己的世袭领地（奥地利、匈牙利、捷克等），神圣罗马帝国越来越成为一个空壳。宗教改革（16世纪）和三十年战争（1618-1648年）对帝国造成了致命打击——《威斯特伐利亚和约》（1648年）确认了各邦国的主权，皇帝只是名义上的共主。

到18世纪末，神圣罗马帝国境内有超过300个独立或半独立的政治实体——既有像奥地利、普鲁士这样的大邦国，也有无数个骑士领地、自由城市和教会领地，有些领地甚至只有一个村庄那么大。帝国议会（Reichstag）形同虚设，皇帝没有常备军，没有统一的法律和税收。

1806年，拿破仑在奥斯特里茨战役中大败奥俄联军后，逼迫神圣罗马帝国皇帝弗朗茨二世宣布放弃神圣罗马皇帝的称号，只保留奥地利皇帝的头衔。延续了844年的神圣罗马帝国正式终结。

尽管神圣罗马帝国不是一个真正意义上的统一国家，但它在欧洲历史上扮演了重要角色：
- 它是德意志民族认同的重要载体，对后来的德意志统一产生了深远影响。
- 它的分权传统（皇帝与诸侯、教会的权力制衡）为欧洲的多元政治格局埋下了伏笔。
- 它的存在使得德意志地区长期分裂，这也是德国在近代姗姗来迟的重要原因之一。`,
